// Spike step 1: try to parse Gantt text through Mermaid's own internal parser+db
// with zero DOM shim, to check the "no browser needed" hope. It fails — see spike.md
// Finding 2. Kept as a reproduction script, not something the product runs.
//
// Run: npm install (in this directory) && node test-parse-no-dom.mjs
//
// NOTE: the import path below contains a content hash (`FUAMR5RP`) generated by
// Mermaid's bundler for this exact 12.0.0 build. If you reinstall a different
// mermaid version, find the current name with:
//   ls node_modules/mermaid/dist/chunks/mermaid.core/ | grep ganttDiagram
import { diagram } from 'mermaid/dist/chunks/mermaid.core/ganttDiagram-FUAMR5RP.mjs';

const text = `gantt
    title Adoption d'un logiciel
    dateFormat YYYY-MM-DD
    excludes weekends
    section Cadrage
    Recueil besoins      :done,    des1, 2026-01-05, 5d
    Choix outil          :active,  des2, after des1, 3d
    section Deploiement
    Formation            :crit,    des3, after des2, 4d
    Go-live              :milestone, des4, after des3, 0d
    Suivi post go-live   :         des5, after des4, 10d
`;

diagram.db.clear();
diagram.parser.yy = diagram.db;
diagram.parser.parse(text);

console.log('title:', diagram.db.getDiagramTitle());
console.log('tasks:', diagram.db.getTasks().length);
